if(EditorApplication.isPlaying)throw new System.Exception("Edit mode required");
if(UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.ExcavationRounds>())return "Round UI already exists; inspect before modifying";
var player=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerController>();var mining=player.visual.GetComponent<Bulldozer.Player.MinerMining>();var safe=mining.cargoLabel.transform.parent;var font=mining.cargoLabel.font;
RectTransform Rect(string name,Transform parent,Vector2 size,Vector2 pos){var go=new GameObject(name,typeof(RectTransform));var r=go.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=r.pivot=new Vector2(.5f,.5f);r.sizeDelta=size;r.anchoredPosition=pos;return r;}
TMPro.TMP_Text Text(string name,Transform parent,string value,Vector2 size,Vector2 pos,float fontSize){var r=Rect(name,parent,size,pos);var t=r.gameObject.AddComponent<TMPro.TextMeshProUGUI>();t.font=font;t.text=value;t.fontSize=fontSize;t.color=Color.white;t.alignment=TMPro.TextAlignmentOptions.Center;t.raycastTarget=false;return t;}
var owner=new GameObject("Excavation Rounds");var rounds=owner.AddComponent<Bulldozer.Player.ExcavationRounds>();rounds.player=player;rounds.equipment=player.visual.GetComponent<Bulldozer.Player.MinerEquipment>();rounds.production=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MiningProduction>();
rounds.roundLabel=Text("Excavation Progress",safe,"EXCAVATION 1  |  78 ROCKS LEFT",new Vector2(420,32),Vector2.zero,18);var hud=rounds.roundLabel.rectTransform;hud.anchorMin=hud.anchorMax=hud.pivot=new Vector2(1,1);hud.anchoredPosition=new Vector2(-24,-100);rounds.roundLabel.alignment=TMPro.TextAlignmentOptions.Right;
var overlay=Rect("Excavation Complete Overlay",safe,Vector2.zero,Vector2.zero);overlay.anchorMin=Vector2.zero;overlay.anchorMax=Vector2.one;overlay.offsetMin=overlay.offsetMax=Vector2.zero;var bg=overlay.gameObject.AddComponent<UnityEngine.UI.Image>();bg.color=new Color(.015f,.025f,.03f,.82f);rounds.completionPanel=overlay.gameObject.AddComponent<CanvasGroup>();
var card=Rect("Completion Card",overlay,new Vector2(580,370),Vector2.zero);card.gameObject.AddComponent<UnityEngine.UI.Image>().color=new Color(.055f,.085f,.09f,1);
rounds.heading=Text("Heading",card,"EXCAVATION COMPLETE",new Vector2(530,60),new Vector2(0,130),28);
rounds.summary=Text("Summary",card,"Completion bonus",new Vector2(520,170),new Vector2(0,15),21);
var button=Rect("Next Excavation",card,new Vector2(470,58),new Vector2(0,-133));button.gameObject.AddComponent<UnityEngine.UI.Image>().color=new Color(.78f,.55f,.22f);rounds.nextButton=button.gameObject.AddComponent<UnityEngine.UI.Button>();Text("Label",button,"NEXT EXCAVATION",new Vector2(450,52),Vector2.zero,23);
overlay.gameObject.SetActive(false);
var fade=Rect("Excavation Transition Fade",safe.GetComponentInParent<Canvas>().transform,Vector2.zero,Vector2.zero);fade.anchorMin=Vector2.zero;fade.anchorMax=Vector2.one;fade.offsetMin=fade.offsetMax=Vector2.zero;fade.gameObject.AddComponent<UnityEngine.UI.Image>().color=new Color(.015f,.025f,.03f,1);rounds.fade=fade.gameObject.AddComponent<CanvasGroup>();rounds.fade.alpha=0;rounds.fade.blocksRaycasts=false;
foreach(var r in UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith("Natural"))){r.naturalBoulder=true;EditorUtility.SetDirty(r);}
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(owner.scene);UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();return "Round progress HUD, completion card and next-excavation button wired";
